// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    // allow the owner (this test contract, set as owner at deployment) to receive ETH
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: any positive, realistic funding amount kept well
        // below wei-level extremes so the internal transfer cannot overflow/gas-fail
        amount = bound(amount, 1, 1_000_000 ether);

        // fund the contract directly (depositsCount stays 0, so depositsCount < balance)
        vm.deal(address(c), amount);

        // owner is the deployer (this contract); drive the entry point
        vm.prank(address(this));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Reference rule: for ANY admissible amount, withdrawAll succeeds and
        // drains the FULL contract balance. The mutant sends only depositsCount
        // (here 0) wei, leaving the whole amount stuck in the contract.
        assertTrue(ok && address(c).balance == 0);
    }
}
